export type ReportColumn = { key: string; label: string };

const escapeHtml = (value: unknown) =>
  String(value ?? '').replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char] as string));

export const BIZIM_VINC_LOGO_B64 = "data:image/png;base64,";

export function downloadExcelReport(filename: string, title: string, columns: ReportColumn[], rows: Record<string, unknown>[], summaryStats?: { label: string; value: string }[]) {
  const header = columns.map((col) => `<th style="background:#087f5b;color:#ffffff;border:1px solid #055a40;padding:8px 10px;font-size:12px;font-weight:bold;text-align:left;">${escapeHtml(col.label)}</th>`).join('');
  const body = rows.map((row, idx) => {
    const bg = idx % 2 === 0 ? '#ffffff' : '#f0fdf4';
    return `<tr style="background:${bg};">${columns.map((col) => `<td style="border:1px solid #cde9d8;padding:7px 10px;font-size:11px;color:#12352a;">${escapeHtml(row[col.key])}</td>`).join('')}</tr>`;
  }).join('');

  const statsHtml = summaryStats && summaryStats.length > 0 ? `
    <table style="margin-bottom:14px;border:none;">
      <tr>
        ${summaryStats.map((s) => `
          <td style="background:#f0fdf4;border:1px solid #bbf7d0;padding:6px 12px;font-size:11px;font-weight:bold;color:#065f46;">
            ${escapeHtml(s.label)}: <span style="font-size:12px;color:#052e16;font-weight:900;">${escapeHtml(s.value)}</span>
          </td>
        `).join('')}
      </tr>
    </table>
  ` : '';

  const html = `<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: 'Segoe UI', Arial, sans-serif; color: #12352a; background: #ffffff; padding: 18px; }
  .header-box { border-bottom: 3px solid #087f5b; padding-bottom: 12px; margin-bottom: 14px; }
  .title { color: #087f5b; font-size: 18px; font-weight: bold; margin: 0; }
  .sub { font-size: 11px; color: #166534; margin-top: 3px; }
  table { border-collapse: collapse; width: 100%; }
</style>
</head>
<body>
<div class="header-box">
  <table style="border:none;width:100%;">
    <tr>
      <td style="border:none;vertical-align:middle;width:240px;">
        <img src="${BIZIM_VINC_LOGO_B64}" style="height:48px;width:auto;" alt="BİZİM VİNÇ ERP">
      </td>
      <td style="border:none;vertical-align:middle;">
        <div class="title">${escapeHtml(title)}</div>
        <div class="sub">BİZİM VİNÇ ERP · En derinden, en yükseklere · Belge Tarihi: ${new Date().toLocaleString('tr-TR')}</div>
      </td>
      <td style="border:none;vertical-align:middle;text-align:right;">
        <span style="border:1.5px dashed #059669;background:#ecfdf5;color:#065f46;padding:5px 10px;font-size:10px;font-weight:bold;border-radius:4px;">
          ★ RESMİ KURUMSAL RAPOR
        </span>
      </td>
    </tr>
  </table>
</div>
${statsHtml}
<table>
  <thead><tr>${header}</tr></thead>
  <tbody>${body}</tbody>
</table>
<div style="margin-top:16px;font-size:10px;color:#64748b;text-align:right;border-top:1px solid #e2e8f0;padding-top:6px;">
  Bu belge Bizim Vinç ERP Muhasebe ve Operasyon Sistemi tarafından üretilmiştir.
</div>
</body>
</html>`;

  const blob = new Blob(['\ufeff' + html], { type: 'application/vnd.ms-excel;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename.endsWith('.xls') ? filename : `${filename}.xls`;
  link.click();
  URL.revokeObjectURL(url);
}

export function downloadHtmlReport(filename: string, title: string, columns: ReportColumn[], rows: Record<string, unknown>[], summaryStats?: { label: string; value: string }[]) {
  const header = columns.map((col) => `<th>${escapeHtml(col.label)}</th>`).join('');
  const body = rows.map((row) => `<tr>${columns.map((col) => `<td>${escapeHtml(row[col.key])}</td>`).join('')}</tr>`).join('');

  const statsHtml = summaryStats && summaryStats.length > 0 ? `
    <div class="stats-grid">
      ${summaryStats.map((s) => `
        <div class="stat-card">
          <div class="stat-label">${escapeHtml(s.label)}</div>
          <div class="stat-value">${escapeHtml(s.value)}</div>
        </div>
      `).join('')}
    </div>
  ` : '';

  const html = `<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<title>${escapeHtml(title)} - BİZİM VİNÇ ERP</title>
<style>
  body { font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #f0fdf4; color: #0f172a; padding: 28px; margin: 0; }
  .container { max-width: 1200px; margin: 0 auto; background: #ffffff; border-radius: 16px; box-shadow: 0 10px 30px rgba(8, 127, 91, 0.08); border: 1px solid #bbf7d0; padding: 28px; position: relative; }
  .hologram-seal { position: absolute; top: 20px; right: 24px; display: inline-flex; align-items: center; gap: 6px; padding: 6px 14px; background: linear-gradient(135deg, #10b981 0%, #059669 100%); color: #ffffff; font-size: 10px; font-weight: 800; border-radius: 9999px; letter-spacing: 0.5px; box-shadow: 0 2px 8px rgba(16, 185, 129, 0.25); }
  .header { display: flex; align-items: center; gap: 18px; border-bottom: 2px solid #10b981; padding-bottom: 16px; margin-bottom: 20px; }
  .logo { height: 54px; width: auto; object-fit: contain; }
  .header-text h1 { margin: 0; font-size: 22px; color: #064e3b; font-weight: 800; }
  .header-text p { margin: 4px 0 0; font-size: 12px; color: #047857; }
  .stats-grid { display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 20px; }
  .stat-card { background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 10px; padding: 10px 16px; min-width: 130px; }
  .stat-label { font-size: 11px; color: #065f46; font-weight: 600; text-transform: uppercase; }
  .stat-value { font-size: 17px; font-weight: 900; color: #064e3b; font-family: monospace; margin-top: 2px; }
  table { width: 100%; border-collapse: collapse; margin-top: 14px; font-size: 12px; }
  th { background: #064e3b; color: #ffffff; text-align: left; padding: 10px 12px; font-weight: 700; border: 1px solid #047857; }
  td { padding: 9px 12px; border: 1px solid #e2e8f0; color: #1e293b; }
  tr:nth-child(even) { background: #f8fafc; }
  tr:hover { background: #f0fdf4; }
  .footer { margin-top: 24px; padding-top: 14px; border-top: 1px solid #e2e8f0; display: flex; justify-content: space-between; align-items: center; font-size: 11px; color: #64748b; }
  .stamp-box { border: 1.5px dashed #059669; border-radius: 8px; padding: 8px 20px; text-align: center; color: #064e3b; font-weight: bold; font-size: 10px; background: #ecfdf5; }
  @media print { body { background: #ffffff; padding: 0; } .container { box-shadow: none; border: none; padding: 0; } }
</style>
</head>
<body>
<div class="container">
  <div class="hologram-seal">★ RESMİ KURUMSAL RAPOR</div>
  <div class="header">
    <img src="${BIZIM_VINC_LOGO_B64}" class="logo" alt="BİZİM VİNÇ ERP">
    <div class="header-text">
      <h1>${escapeHtml(title)}</h1>
      <p>BİZİM VİNÇ ERP · En derinden, en yükseklere · Belge Tarihi: ${new Date().toLocaleString('tr-TR')}</p>
    </div>
  </div>
  ${statsHtml}
  <table>
    <thead><tr>${header}</tr></thead>
    <tbody>${body}</tbody>
  </table>
  <div class="footer">
    <div>
      <div><b>Bizim Vinç Saha ve Muhasebe Yönetim Sistemi</b></div>
      <div>Bu doküman sistem üzerinden doğrulanmış kurumsal verileri içerir.</div>
    </div>
    <div class="stamp-box">
      BİZİM VİNÇ ERP<br>
      ONAYLI VE MÜHÜRLÜ DÖKÜM
    </div>
  </div>
</div>
</body>
</html>`;

  const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename.endsWith('.html') ? filename : `${filename}.html`;
  link.click();
  URL.revokeObjectURL(url);
}

export function printReport(title: string, columns: ReportColumn[], rows: Record<string, unknown>[], summaryStats?: { label: string; value: string }[]) {
  const header = columns.map((col) => `<th>${escapeHtml(col.label)}</th>`).join('');
  const body = rows.map((row) => `<tr>${columns.map((col) => `<td>${escapeHtml(row[col.key])}</td>`).join('')}</tr>`).join('');
  const reportWindow = window.open('', '_blank', 'noopener,noreferrer');
  if (!reportWindow) return;

  const statsHtml = summaryStats && summaryStats.length > 0 ? `
    <div style="display:flex;gap:12px;margin-bottom:12px;">
      ${summaryStats.map((s) => `
        <div style="background:#f0fdf4;border:1px solid #bbf7d0;padding:6px 12px;border-radius:6px;">
          <span style="font-size:10px;color:#065f46;font-weight:bold;">${escapeHtml(s.label)}:</span>
          <span style="font-size:11px;color:#064e3b;font-weight:900;margin-left:4px;">${escapeHtml(s.value)}</span>
        </div>
      `).join('')}
    </div>
  ` : '';

  reportWindow.document.write(`<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<title>${escapeHtml(title)}</title>
<style>
  @page { size: A4; margin: 12mm; }
  body { font-family: Arial, sans-serif; color: #0f172a; margin: 0; padding: 0; }
  .header { display: flex; align-items: center; justify-content: space-between; border-bottom: 2px solid #087f5b; padding-bottom: 8px; margin-bottom: 12px; }
  .logo { height: 46px; width: auto; }
  h1 { margin: 0; color: #087f5b; font-size: 17px; }
  p { margin: 2px 0; font-size: 10px; color: #065f46; }
  .badge { border: 1px solid #087f5b; color: #087f5b; padding: 3px 6px; border-radius: 4px; font-size: 9px; font-weight: bold; background:#ecfdf5; }
  table { border-collapse: collapse; width: 100%; font-size: 10px; }
  th { background: #087f5b; color: white; border: 1px solid #055a40; padding: 6px 8px; text-align: left; }
  td { border: 1px solid #cbd5e1; padding: 5px 8px; }
  tr:nth-child(even) { background: #f8fafc; }
  .footer { margin-top: 16px; border-top: 1px solid #cbd5e1; padding-top: 8px; display: flex; justify-content: space-between; font-size: 9px; color: #64748b; }
</style>
</head>
<body>
<div class="header">
  <div style="display:flex;align-items:center;gap:12px;">
    <img src="${BIZIM_VINC_LOGO_B64}" class="logo" alt="BİZİM VİNÇ ERP">
    <div>
      <h1>${escapeHtml(title)}</h1>
      <p>En derinden, en yükseklere · Tarih: ${new Date().toLocaleString('tr-TR')}</p>
    </div>
  </div>
  <div class="badge">★ RESMİ ERP ÇIKTISI</div>
</div>
${statsHtml}
<table>
  <thead><tr>${header}</tr></thead>
  <tbody>${body}</tbody>
</table>
<div class="footer">
  <div>Bizim Vinç ERP Sistem Çıktısı</div>
  <div>Yetkili İmza & Kaşe: ____________________</div>
</div>
<script>window.onload=function(){window.print();}</script>
</body>
</html>`);
  reportWindow.document.close();
}
